import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CT6jiXWi.js";const g=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"federation/getting-started/index.md","filePath":"federation/getting-started/index.md","lastUpdated":1783777611000}'),d={name:"federation/getting-started/index.md"};function i(n,e,s,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>This section walks through the shortest path from a clean CAP app to a working federation — delegation, replication, and cache, one at a time.</p><table tabindex="0"><thead><tr><th>Page</th><th>What you&#39;ll do</th></tr></thead><tbody><tr><td><a href="./installation.html">Installation</a></td><td>Install the plugin and its peer dependencies.</td></tr><tr><td><a href="./first-delegation.html">First Delegation</a></td><td>Annotate a consumption view with <code>@federation.delegate</code> and forward OData queries to a remote service.</td></tr><tr><td><a href="./first-replication.html">First Replication</a></td><td>Annotate a consumption view with <code>@federation.replicate</code> and sync remote data into the local DB on a schedule.</td></tr><tr><td><a href="./first-cache.html">First Cache</a></td><td>Add caching to a delegate — response cache (<code>cds-caching</code>) or entity cache (SQLite snapshot).</td></tr></tbody></table><h2 id="patterns" tabindex="-1">Patterns <a class="header-anchor" href="#patterns" aria-label="Permalink to &quot;Patterns&quot;">​</a></h2><p>Once the basics click, these task-focused pages show how local and remote data combine in real scenarios. Each page mirrors behavior that is covered by tests in <a href="https://github.com/mikezaschka/cds-data/tree/main/packages/cds-data-federation/test/integration" target="_blank" rel="noreferrer"><code>packages/cds-data-federation/test/integration/</code></a> and <a href="https://github.com/mikezaschka/cds-data/tree/main/packages/cds-data-pipeline/test/integration" target="_blank" rel="noreferrer"><code>packages/cds-data-pipeline/test/integration/</code></a>.</p><table tabindex="0"><thead><tr><th>Page</th><th>When to reach for it</th></tr></thead><tbody><tr><td><a href="./joining-local-with-remote.html">Joining Local with Remote</a></td><td>A local entity (reviews, bookmarks, notes) references a federated one. Covers cross-service <code>$expand</code>, navigation, and <code>$filter</code>.</td></tr><tr><td><a href="./extending-remote-with-local.html">Extending Remote with Local</a></td><td>A federated entity needs local-only children (bookmarks, tags, approval status). The reverse direction of the page above.</td></tr><tr><td><a href="./cross-provider-mashup.html">Cross-Provider Mashup</a></td><td>One local entity stitches data from two different remote services in a single response.</td></tr><tr><td><a href="./mixing-delegate-and-replicate.html">Mixing Delegate and Replicate</a></td><td>Live data via delegate, reference data via replicate — both strategies in one service.</td></tr><tr><td><a href="./local-analytics-over-replicated.html">Local Analytics over Replicated Data</a></td><td>SQL aggregations, joins, <code>DISTINCT</code>, <code>$apply</code> over replicated remote tables.</td></tr></tbody></table><p>!!! tip &quot;Prefer learning from runnable examples?&quot; The root <a href="https://github.com/mikezaschka/cds-data/tree/main/examples" target="_blank" rel="noreferrer"><code>examples/</code></a> folder contains four servers you can boot in a single command (<code>npm run examples:start</code>) with Fiori Elements UIs aggregated in a launchpad. Every tile maps to one of the getting-started scenarios.</p><pre><code>For focused, single-capability apps (one per strategy), see the [`packages/cds-data-federation/examples/`](https://github.com/mikezaschka/cds-data/tree/main/packages/cds-data-federation/examples) catalogue — numbered demos for delegate, replicate, cross-service expand, caching, cross-provider mashup, OData V2, HCQL, and MCP.\n</code></pre>',8)])])}const m=t(d,[["render",i]]);export{g as __pageData,m as default};
